<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {api,errorText} from '../api/client'
import {items} from '../api'
import {employeeTitle} from '../api/employee-labels'
import OperationForm from './OperationForm.vue'
const props=defineProps<{user:any}>();const emit=defineEmits(['selfReset','changed'])
const classes=ref<any[]>([]),departments=ref<any[]>([])
const employees=ref<any[]>([]),students=ref<any[]>([]),kind=ref('ALL'),search=ref(''),busy=ref(false),error=ref(''),target=ref<any>(null),operation=ref<'reset'|'edit'>('reset'),manualId=ref(''),selfReset=ref(false)
const rows=computed(()=>[...employees.value.map(u=>({...u,kind:'EMPLOYEE',label:employeeTitle(u,classes.value,departments.value),accountId:u.id})),...students.value.map(u=>({...u,kind:'STUDENT',label:'学生',profileId:u.id,username:''}))].filter(u=>(kind.value==='ALL'||u.kind===kind.value)&&(!search.value||[u.realName,u.username,u.id].some(v=>String(v||'').includes(search.value)))))
async function load(){if(!props.user.isAdmin)return;busy.value=true;error.value='';try{const [people,first,cls,depts]=await Promise.all([api.get('/organization/users'),api.get('/employees/students',{page:1,page_size:100}),api.get('/organization/classes'),api.get('/organization/departments')]);classes.value=items(cls);departments.value=items(depts);const all=items(first);for(let page=2;all.length<(first.total||0);page++){const more=items(await api.get('/employees/students',{page,page_size:100}));if(!more.length)break;all.push(...more)}employees.value=items(people);students.value=all}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function select(row:any,mode:'reset'|'edit'){busy.value=true;error.value='';try{let account=row;if(row.kind==='STUDENT'){const detail=await api.get('/employees/students/'+row.profileId);account={...row,accountId:detail.userId,contactInfo:detail.mobile};if(!account.accountId)throw new Error('学生账号编号缺失，请刷新档案后重试')}operation.value=mode;target.value=account}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function manual(){if(!/^[1-9]\d*$/.test(manualId.value)){error.value='请输入有效的账号编号';return}operation.value='reset';target.value={accountId:manualId.value,realName:'账号编号 '+manualId.value}}
function saved(){if(operation.value==='reset'&&String(target.value?.accountId)===String(props.user.id)){selfReset.value=true;return}emit('changed');load()}
function close(){target.value=null;if(selfReset.value)emit('selfReset')}
onMounted(load)
</script>
<template><section v-if="user.isAdmin" class="account-management"><div class="page-heading"><div><span class="eyebrow">SYSTEM ACCOUNTS</span><h1>系统账号管理</h1><p>统一维护员工与学生账号，管理员可重置各类账号的登录密码。</p></div><button class="btn outline" :disabled="busy" @click="load">刷新账号</button></div><div class="account-summary"><article><span>有效员工账号</span><strong>{{employees.length}}</strong></article><article><span>学生档案账号</span><strong>{{students.length}}</strong></article><article><span>密码重置规则</span><p>生成临时密码 · 首次登录修改</p></article></div><section class="paper"><div class="account-filter"><div class="business-tabs"><button v-for="(label,value) in {ALL:'全部账号',EMPLOYEE:'员工与管理员',STUDENT:'学生账号'}" :key="value" :class="{active:kind===value}" @click="kind=value">{{label}}</button></div><label>搜索账号<input v-model="search" placeholder="姓名、员工登录账号或列表编号"></label></div><p v-if="error" class="error-callout">{{error}}</p><p v-if="busy" class="loading-callout">正在加载账号…</p><div class="table-scroll"><table><thead><tr><th>姓名</th><th>身份</th><th>登录账号 / 档案</th><th>账号操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.kind+row.id"><td><strong>{{row.realName}}</strong><span v-if="String(row.accountId)===String(user.id)" class="subtle-tag">本人</span></td><td>{{row.label}}</td><td>{{row.username||'详见学生档案'}}</td><td><div class="row-actions"><button :disabled="busy" @click="select(row,'reset')">重置密码</button><button v-if="row.kind==='EMPLOYEE'" :disabled="busy" @click="select(row,'edit')">账号配置</button><a v-else :href="'#/app/students/'+row.profileId">查看学生</a></div></td></tr><tr v-if="!rows.length&&!busy"><td colspan="4" class="empty">没有符合条件的账号</td></tr></tbody></table></div></section><section class="paper manual-account"><h3>按账号编号重置</h3><p>停用账号或未出现在当前列表中的账号，可使用已核实的账号编号办理。此处填写登录用户编号。</p><form @submit.prevent="manual"><label>账号编号<input v-model="manualId" inputmode="numeric" required placeholder="请输入已核实的账号编号"></label><button class="btn outline" :disabled="busy">核对重置密码</button></form></section><OperationForm v-if="target" :key="operation+target.accountId" :title="operation==='reset'?'重置密码 · '+target.realName:'账号配置 · '+target.realName" :path="operation==='reset'?'/api/v1/management/users/{user_id}/password-reset':'/api/v1/management/users/{user_id}'" :method="operation==='reset'?'POST':'PATCH'" :params="{user_id:target.accountId}" :record="target" @close="close" @saved="saved"/></section><section v-else class="paper empty">仅系统管理员可维护账号密码。</section></template>
